import java.util.*;

class Solution {
    public List<Boolean> searchGrid(int[][] grid, int[] queries) {
        int rows = grid.length, cols = grid[0].length;
        List<Boolean> result = new ArrayList<>();
        for (int x : queries) {
            int lo = 0, hi = rows * cols - 1;
            boolean found = false;
            while (lo <= hi) {
                int mid = (lo + hi) / 2;
                int v = grid[mid / cols][mid % cols];   // flat index -> cell
                if (v == x) { found = true; break; }
                if (v < x) lo = mid + 1;
                else hi = mid - 1;
            }
            result.add(found);
        }
        return result;
    }
}
